function solve(input) {
  const seen = new Set();
  const balances = Object.create(null);
  for (const { eventId, account, delta } of input) {
    if (seen.has(eventId)) continue;
    seen.add(eventId);
    if (Object.prototype.hasOwnProperty.call(balances, account)) {
      balances[account] += delta;
    } else {
      balances[account] = delta;
    }
  }
  const accounts = Object.keys(balances).sort();
  return accounts.map(account => [account, balances[account]]);
}
