function solve(input) {
    const { nodes, edges } = input;
    const nodeSet = new Set(nodes);
    const adj = new Map();
    const inDegree = new Map();

    for (const n of nodes) {
        adj.set(n, new Set());
        inDegree.set(n, 0);
    }

    for (const [u, v] of edges) {
        if (u === v) return null;
        if (!nodeSet.has(u) || !nodeSet.has(v)) continue;
        if (adj.get(u).has(v)) continue;
        adj.get(u).add(v);
        inDegree.set(v, inDegree.get(v) + 1);
    }

    // Use a sorted structure to always pick lexicographically smallest
    // Since we need to repeatedly extract min, use a sorted array or min-heap
    // For simplicity with no external libs, use a sorted array approach
    // But better: use a binary heap or just sort each time (nodes count likely small)
    // Let's use a simple approach: maintain a sorted list of available nodes

    const available = [];
    for (const n of nodes) {
        if (inDegree.get(n) === 0) {
            available.push(n);
        }
    }
    available.sort();

    const result = [];
    while (available.length > 0) {
        // Pick the lexicographically smallest
        const u = available.shift();
        result.push(u);

        for (const v of adj.get(u)) {
            inDegree.set(v, inDegree.get(v) - 1);
            if (inDegree.get(v) === 0) {
                // Insert into available in sorted order
                let inserted = false;
                for (let i = 0; i < available.length; i++) {
                    if (v < available[i]) {
                        available.splice(i, 0, v);
                        inserted = true;
                        break;
                    }
                }
                if (!inserted) {
                    available.push(v);
                }
            }
        }
    }

    if (result.length !== nodes.length) {
        return null;
    }

    return result;
}
