function solve(input) {
  const cache = new Map();
  const results = [];

  for (const op of input) {
    if (op.op === "put") {
      const { t, key, value, ttl } = op;
      const expireAt = t + ttl;
      cache.set(key, { value, expireAt });
    } else if (op.op === "get") {
      const { t, key } = op;
      const entry = cache.get(key);
      if (entry === undefined) {
        results.push(null);
      } else if (t >= entry.expireAt) {
        cache.delete(key);
        results.push(null);
      } else {
        results.push(entry.value);
      }
    } else if (op.op === "delete") {
      const { key } = op;
      cache.delete(key);
    }
  }

  return results;
}
