function solve({ document, pointer }) {
  let current = document;
  if (pointer === '') return { found: true, value: current };
  if (pointer[0] !== '/') return { found: false };
  const tokens = pointer.slice(1).split('/');
  for (const raw of tokens) {
    if (raw === '') {
      if (current == null || typeof current !== 'object') return { found: false };
      continue;
    }
    if (current == null || typeof current !== 'object') return { found: false };
    let decoded = '';
    for (let i = 0; i < raw.length; i++) {
      if (raw[i] === '~') {
        i++;
        if (raw[i] === '0') decoded += '~';
        else if (raw[i] === '1') decoded += '/';
        else return { found: false };
      } else {
        decoded += raw[i];
      }
    }
    if (Array.isArray(current)) {
      if (!/^(0|[1-9]\d*)$/.test(decoded)) return { found: false };
      current = current[decoded];
    } else {
      if (!Object.prototype.hasOwnProperty.call(current, decoded)) return { found: false };
      current = current[decoded];
    }
  }
  return { found: true, value: current };
}
